export const ASPEN_STD_LIB_WASM_BASE64 =
  "";

let cachedWasmBytes: Uint8Array | undefined;

/**
 * Decodes the pre-bundled `@modelscript/aspen-std-lib` `runtime.wasm` binary in Node.js, Browsers, or Web Workers.
 */
export function getAspenStdLibWasmBytes(): Uint8Array {
  if (!cachedWasmBytes) {
    cachedWasmBytes = decodeBase64Wasm(ASPEN_STD_LIB_WASM_BASE64);
  }
  return cachedWasmBytes;
}
